out = {"levels": {str(i+1): [dict(t=a, d=b, zh=c, vi=d, k=e) for a,b,c,d,e in Lx] for i,Lx in enumerate([L1,L2,L3])},
       "notes": {str(k): [dict(t=a, d=b, ex=[dict(zh=x, vi=y) for x,y in ex]) for a,b,ex in v] for k,v in NOTES.items()},
       "ex": {"fill":[dict(q=a,h=b,a=c) for a,b,c in EX["fill"]], "order":[dict(q=a,a=b) for a,b in EX["order"]], "trans":[dict(q=a,a=b) for a,b in EX["trans"]], "fix":[dict(q=a,a=b,why=c) for a,b,c in EX["fix"]]},
       "src": "Theo tài liệu “Tổng hợp ngữ pháp tiếng Trung HSK 1–3” của Kien"}
for lv in out["levels"].values():
    for p in lv: assert p["k"] in p["zh"], p
